import os
import ast

keywords = ["create", "update", "delete", "save", "write", "post", "put", "patch"]

def analyze():
    base_dir = "app"
    results = []
    for root, _, files in os.walk(base_dir):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r") as f:
                content = f.read()

            if "legacy_auth" not in content:
                continue

            # Parse with AST
            tree = ast.parse(content)
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    # Check if legacy_auth is called in this function
                    has_legacy_auth = False
                    for subnode in ast.walk(node):
                        if isinstance(subnode, ast.Call) and isinstance(subnode.func, ast.Name) and subnode.func.id == "legacy_auth":
                            has_legacy_auth = True
                            break

                    if has_legacy_auth:
                        # Get function source/text representation
                        # We can just check the AST or the lines of code for this function
                        func_lines = content.splitlines()[node.lineno - 1 : node.end_lineno]
                        func_text = "\n".join(func_lines).lower()

                        # Also check the file path
                        path_lower = path.lower()

                        matched_kw = []
                        for kw in keywords:
                            if kw in func_text or kw in path_lower:
                                matched_kw.append(kw)

                        scope = "write" if matched_kw else "read"
                        results.append({
                            "file": path,
                            "function": node.name,
                            "matched": matched_kw,
                            "scope": scope,
                            "has_payload": "payload" in func_text
                        })

    # Print results
    for r in sorted(results, key=lambda x: x["file"]):
        print(f"{r['file']}:{r['function']} -> scope={r['scope']} (matched: {r['matched']}, has_payload: {r['has_payload']})")

if __name__ == "__main__":
    analyze()

