import os
import ast

def migrate():
    base_dir = "app"
    for root, _, files in os.walk(base_dir):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r") as f:
                content = f.read()

            if "legacy_auth" not in content:
                continue

            lines = content.splitlines()

            # Find the import line and replace it
            for i, line in enumerate(lines):
                if "from app.auth import legacy_auth" in line:
                    lines[i] = line.replace("legacy_auth", "new_auth")

            # Parse with AST to locate functions and their line ranges
            tree = ast.parse(content)
            func_scopes = {} # map of (start_line, end_line) -> scope

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    # Check if 'payload' is in function arguments
                    has_payload = any(arg.arg == "payload" for arg in node.args.args)
                    scope = "write" if has_payload else "read"
                    func_scopes[(node.lineno, node.end_lineno)] = scope

            # Now replace legacy_auth call sites within the line ranges of the functions
            for (start, end), scope in func_scopes.items():
                for i in range(start - 1, end):
                    if "legacy_auth(" in lines[i]:
                        line = lines[i]
                        idx = line.find("legacy_auth(")
                        while idx != -1:
                            close_idx = line.find(")", idx)
                            if close_idx != -1:
                                arg = line[idx + len("legacy_auth(") : close_idx]
                                old_call = f"legacy_auth({arg})"
                                new_call = f'new_auth({arg}, scope="{scope}")'
                                line = line.replace(old_call, new_call)
                            idx = line.find("legacy_auth(", idx + 1)
                        lines[i] = line

            # Write back the migrated file
            with open(path, "w") as f:
                f.write("\n".join(lines) + "\n")
            print(f"Migrated {path}")

if __name__ == "__main__":
    migrate()
